  const companyUsage = useMemo(() => { const usage = new Map<string, CompanyUsage>(); companies.forEach((company: Company) => usage.set(company.id, { applications: 0, contacts: 0, businessGroups: 0, total: 0 })); applications.forEach((application: JobApplication) => { const id = application.company?.id; const current = usage.get(id); if (current) usage.set(id, { ...current, applications: current.applications + 1, total: current.total + 1 }); }); contacts.forEach((contact: NetworkingContact) => { const id = contact.company?.id; const current = usage.get(id); if (current) usage.set(id, { ...current, contacts: current.contacts + 1, total: current.total + 1 }); }); businessGroups.forEach((group: BusinessGroup) => { const current = usage.get(group.company?.id); if (current) usage.set(group.company?.id, { ...current, businessGroups: current.businessGroups + 1, total: current.total + 1 }); }); return usage; }, [applications, businessGroups, companies, contacts]);
